// actionReaders is the sentence naming the rules that read krateo.action,
// derived from the schema: the keys whose closed set is per action, each
// with the actions that declare a set.
func actionReaders(s *schema) string {
	var rules []string
	for _, k := range s.Keys {
		var actions []string
		for _, w := range s.Writers {
			for _, a := range slices.Sorted(maps.Keys(k.Writers[w.ID].Actions)) {
				if !slices.Contains(actions, a) {
					actions = append(actions, a)
				}
			}
		}
		if len(actions) > 0 {
			rules = append(rules, "`"+k.Name+"` on `"+strings.Join(actions, "`, `")+"`")
		}
	}
	switch len(rules) {
	case 0:
		return "No rule reads it."
	case 1:
		return "The only rule that reads it is a per-action closed set (above): " + rules[0] + "."
	}
	return "The only rules that read it are the per-action closed sets (above): " + strings.Join(rules, "; ") + "."
}

// actionLiteralsDoc renders the registry section of docs/schema.md.
func actionLiteralsDoc(s *schema) string {
	var b strings.Builder
	b.WriteString(`
## ` + "`krateo.action`" + ` literals

` + "`krateo.action`" + ` is the emit site's own literal. Schema v1 does not enforce
its values: ` + "`Check`" + ` accepts any non-empty literal.
` + actionReaders(s) + `
The literals below are registered so that writers spell the same action the
same way and readers can query by it. A writer registers a literal by adding
it here, in ` + "`internal/schemagen/doc.go`" + `; every action a per-action set
declares must be registered.

| writer | literal | the action |
|---|---|---|
`)
	for _, l := range actionLiterals {
		fmt.Fprintf(&b, "| `%s` | `%s` | %s |\n", l.Writer, l.Literal, l.Action)
	}
	return b.String()
}

func levelCell(r requirement) string {
	mark := ""
	if r.Markable {
		mark = " (mark)"
	}
	switch r.Level {
	case "required":
		return "R" + mark + oneOf(r.Values)
	case "conditional":
		checked := ""
		if r.Check != "" {
			checked = " [checked]"
		}
		return "C: " + cell(r.When) + checked + mark + oneOf(r.Values)
	case "optional":
		return "O" + oneOf(r.Values) + perAction(r.Actions)
	case "not_established":
		return "NE"
	}
	return "—"
}

func keyNotes(k key) string {
	var notes []string
	if len(k.Values) > 0 {
		notes = append(notes, "One of `"+strings.Join(k.Values, "`, `")+"`.")
	}
	if k.ValuesFrom != "" {
		notes = append(notes, "The values are generated from `"+k.ValuesFrom+"`, each entry as `<kind>:<key>`.")
	}
	if k.Marker != "" {
		notes = append(notes, "Marker `"+k.Marker+"`.")
	}
	if k.Identity {
		notes = append(notes, "**Identity.**")
	}
	if k.Asserted {
		notes = append(notes, "**Asserted** (client-chosen).")
	}
	if k.Format != "" {
		notes = append(notes, "Format `"+k.Format+"`.")
	}
	if k.Minimum != nil {
		notes = append(notes, fmt.Sprintf("At least %d.", *k.Minimum))
	}
	if k.LessThan != "" {
		notes = append(notes, "Less than `"+k.LessThan+"` on the same record.")
	}
	if k.OnlyWhen != "" {
		notes = append(notes, "**Only when** `"+k.OnlyWhen+"` holds; anywhere else `Check` reports it `unexpected`.")
	}
	if k.NotWhen != "" {
		notes = append(notes, "**Never when** `"+k.NotWhen+"` holds; there `Check` reports it `unexpected`.")
	}
	if k.CredentialFree {
		notes = append(notes, "**Never on a credential target**; there `Check` reports it `not-for-target`.")
	}
	return k.Description + " " + strings.Join(notes, " ")
}

func cell(s string) string {
	return strings.TrimSpace(strings.NewReplacer("|", `\|`, "<", "&lt;", ">", "&gt;").Replace(s))
}

// oneOf is a requirement's own closed set, as a level cell suffix.
func oneOf(values []string) string {
	if len(values) == 0 {
		return ""
	}
	return ", one of `" + strings.Join(values, "`, `") + "`"
}

// perAction is a per-action closed set in a level cell: each action, sorted,
// with its values.
func perAction(sets map[string][]string) string {
	if len(sets) == 0 {
		return ""
	}
	var parts []string
	for _, a := range slices.Sorted(maps.Keys(sets)) {
		parts = append(parts, "on `"+a+"` one of `"+strings.Join(sets[a], "`, `")+"`")
	}
	return ", " + strings.Join(parts, "; ")
}

// exampleNames are the regions docs/schema.md shows, each marked in the
// examples file by a `// schema.md: <name>` line and closed by
// `// schema.md: end`.
var exampleNames = []string{"controller-emitter", "kept-deletion", "pruned-child"}

var regionMark = regexp.MustCompile(`^\s*// schema\.md: ([a-z-]+)\s*$`)

// exampleRegions returns each named region of src, its common indentation
// removed, so the doc shows the very code the examples' tests run.
func exampleRegions(src []byte) (map[string]string, error) {
	out := map[string]string{}
	var name string
	var lines []string
	for _, l := range strings.Split(string(src), "\n") {
		m := regionMark.FindStringSubmatch(l)
		switch {
		case m == nil && name != "":
			lines = append(lines, l)
		case m == nil:
		case m[1] == "end" && name != "":
			out[name] = dedent(lines)
			name, lines = "", nil
		case m[1] == "end" || name != "":
			return nil, fmt.Errorf("region marker %q out of place", m[1])
		case !slices.Contains(exampleNames, m[1]):
			return nil, fmt.Errorf("unknown region %q, want one of %v", m[1], exampleNames)
		case out[m[1]] != "":
			return nil, fmt.Errorf("region %q: duplicate", m[1])
		default:
			name = m[1]
		}
	}
	if name != "" {
		return nil, fmt.Errorf("region %q is not closed", name)
	}
	for _, n := range exampleNames {
		if strings.TrimSpace(out[n]) == "" {
			return nil, fmt.Errorf("region %q is missing or empty", n)
		}
	}
	return out, nil
}

// dedent removes the leading tabs every non-blank line shares, and ends the
// text with a newline.
func dedent(lines []string) string {
	common := -1
	for _, l := range lines {
		if strings.TrimSpace(l) == "" {
			continue
		}
		n := len(l) - len(strings.TrimLeft(l, "\t"))
		if common < 0 || n < common {
			common = n
		}
	}
	var b strings.Builder
	for _, l := range lines {
		if strings.TrimSpace(l) == "" {
			b.WriteString("\n")
			continue
		}
		b.WriteString(l[common:] + "\n")
	}
	return b.String()
}
